    // An ifacePair is a node in a stack of interface type pairs compared for identity.
    
    template<typename T> requires gocpp::GoStruct<T>
    ifacePair::operator T()
    {
        T result;
        result.x = this->x;
        result.y = this->y;
        result.prev = this->prev;
        return result;
    }

    template<typename T> requires gocpp::GoStruct<T>
    bool ifacePair::operator==(const T& ref) const
    {
        if (x != ref.x) return false;
        if (y != ref.y) return false;
        if (prev != ref.prev) return false;
        return true;
    }

    std::ostream& ifacePair::PrintTo(std::ostream& os) const
    {
        os << '{';
        os << "" << x;
        os << " " << y;
        os << " " << prev;
        os << '}';
        return os;
    }

    std::ostream& operator<<(std::ostream& os, const struct ifacePair& value)
    {
        return value.PrintTo(os);
    }

    bool rec::identical(ifacePair* p, ifacePair* q)
    {
        return p->x == q->x && p->y == q->y || p->x == q->y && p->y == q->x;
    }

    // A comparer is used to compare types.
    
    template<typename T> requires gocpp::GoStruct<T>
    comparer::operator T()
    {
        T result;
        result.ignoreTags = this->ignoreTags;
        result.ignoreInvalids = this->ignoreInvalids;
        return result;
    }

    template<typename T> requires gocpp::GoStruct<T>
    bool comparer::operator==(const T& ref) const
    {
        if (ignoreTags != ref.ignoreTags) return false;
        if (ignoreInvalids != ref.ignoreInvalids) return false;
        return true;
    }

    std::ostream& comparer::PrintTo(std::ostream& os) const
    {
        os << '{';
        os << "" << ignoreTags;
        os << " " << ignoreInvalids;
        os << '}';
        return os;
    }

    std::ostream& operator<<(std::ostream& os, const struct comparer& value)
    {
        return value.PrintTo(os);
    }

